const http = require('http');
const fs = require('fs');
const path = require('path');
const PORT = process.env.PORT || 21000;
const dbFile = path.join(__dirname, 'visitors.json');
let applications = fs.existsSync(dbFile) ? JSON.parse(fs.readFileSync(dbFile, 'utf8')) : [
  {id:'V-1001', visitorName:'张伟', phone:'13800138000', company:'星河科技', hostName:'李娜', hostDept:'产品部', visitDate:'2026-07-28', visitTime:'09:30', reason:'项目沟通', status:'pending', createdAt:new Date().toISOString(), note:''}
];
function save(){fs.writeFileSync(dbFile, JSON.stringify(applications,null,2));}
function send(res, code, data, type='application/json'){res.writeHead(code, {'Content-Type':type+'; charset=utf-8','Access-Control-Allow-Origin':'*'});res.end(type==='application/json'?JSON.stringify(data):data)}
function body(req){return new Promise((ok, bad)=>{let s='';req.on('data',c=>s+=c);req.on('end',()=>{try{ok(s?JSON.parse(s):{})}catch(e){bad(e)}})})}
const html=fs.readFileSync(path.join(__dirname,'index.html'),'utf8');
const server=http.createServer(async (req,res)=>{
  if(req.method==='OPTIONS'){send(res,204,'');return}
  if(req.url==='/'||req.url==='/index.html'){send(res,200,html,'text/html');return}
  if(req.url==='/api/applications'&&req.method==='GET'){send(res,200,{applications});return}
  if(req.url==='/api/applications'&&req.method==='POST'){
    try{const d=await body(req); for(const k of ['visitorName','phone','hostName','visitDate','visitTime','reason']) if(!d[k]) return send(res,400,{error:`请填写${k}`});
      const a={id:'V-'+(1000+applications.length+1),company:d.company||'个人来访',hostDept:d.hostDept||'未填写',note:'',status:'pending',createdAt:new Date().toISOString(),...d};applications.unshift(a);save();send(res,201,a)
    }catch(e){send(res,400,{error:'请求格式错误'})}return
  }
  const m=req.url.match(/^\/api\/applications\/([^/]+)\/(approve|reject|checkin|checkout)$/);
  if(m&&req.method==='POST'){const a=applications.find(x=>x.id===m[1]);if(!a)return send(res,404,{error:'申请不存在'});const action=m[2];
    if(action==='approve'&&a.status==='pending'){a.status='approved';a.note='被访人已审核通过'}
    else if(action==='reject'&&a.status==='pending'){a.status='rejected';a.note='被访人审核未通过'}
    else if(action==='checkin'&&a.status==='approved'){a.status='checked_in';a.checkedInAt=new Date().toISOString()}
    else if(action==='checkout'&&a.status==='checked_in'){a.status='checked_out';a.checkedOutAt=new Date().toISOString()}
    else return send(res,409,{error:'当前状态不可执行该操作'});save();send(res,200,a);return}
  send(res,404,{error:'Not found'});
});server.listen(PORT,'0.0.0.0',()=>console.log(`Visitor system running at http://0.0.0.0:${PORT}`));
